// Moore state machine: transition + output logic, no register.
// (the register-less combinational next state + output function)
module TopModule(input in, input [1:0] state, output [1:0] next_state, output reg out);
    reg [1:0] ns;
    always @(*) begin
        case (state)
            2'b00: begin ns = 2'b00; out = 1'b0; end
            2'b01: begin ns = 2'b01; out = 1'b0; end
            2'b10: begin ns = 2'b10; out = 1'b0; end
            2'b11: begin ns = 2'b01; out = 1'b1; end
        endcase
    end
    assign next_state = ns;
endmodule

