            2'b01: begin next_state_reg = in ? 2'b01 : 2'b01; out = 1'b0; end
            2'b10: begin next_state_reg = in ? 2'b11 : 2'b00; out = 1'b0; end
            2'b11: begin next_state_reg = in ? 2'b00 : 2'b01; out = 1'b1; end
        endcase
    end
    assign next_state = next_state_reg;
