module TopModule (
    input  in,
    input  [1:0] state,
    output [1:0] next_state,
    output out
);
    reg [1:0] ns_table [0:3];
    always @* begin
        ns_table[0] = {2'b00, 2'b01};
        ns_table[1] = {2'b10, 2'b01};
        ns_table[2] = {2'b00, 2'b11};
        ns_table[3] = {2'b10, 2'b01};
        next_state = ns_table[state][in];
        out = (next_state == 2'b10);
    end
